from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Symmetric matrix-matrix multiply kernel:
# C := beta * C + alpha * A * B, where A is stored as a lower-triangular
# symmetric matrix. This closely follows the PolyBench reference kernel,
# but is expressed in Exo and then scheduled for better performance.

@proc
def kernel_symm(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # The triangular k-loop only touches A[i, k] for k <= i and A[i, i],
    # so the -999 entries in the upper triangle of A are never read.
    for i in seq(0, m):
        for j in seq(0, n):
            temp2: DATA_TYPE
            temp1: DATA_TYPE

            temp2 = 0
            # Hoist the common subexpression alpha * B[i, j] so it is
            # computed once per (i, j) instead of once per k.
            temp1 = alpha * B[i, j]

            for k in seq(0, i):
                # Update the upper part of C using the current row of A.
                C[k, j] += temp1 * A[i, k]
                # Accumulate the contribution needed for C[i, j].
                temp2 += B[k, j] * A[i, k]

            # Finish the update of C[i, j].
            C[i, j] = beta * C[i, j] + temp1 * A[i, i] + alpha * temp2

# -----------------------------
# Scheduling for performance
# -----------------------------

# Tile the j-loop to improve spatial locality for B and C and to expose
# a unit-stride inner loop over j within each tile. The tail of the loop
# is handled safely with guards, so N does not need to be divisible by
# the tile size.
J_TILE = 32

kernel_symm = divide_loop(kernel_symm, "j", J_TILE, ("jo", "ji"), tail="guard")

# Clean up the resulting control structure and algebraic expressions.
kernel_symm = simplify(kernel_symm)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_symm (/*ctxt=*/NULL, m, n,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
