        for j in seq(0, n):
            temp2: DATA_TYPE
            temp2 = 0.0
            for k in seq(0, i):
                # Exploit symmetry: A[i, k] == A[k, i]
                #   - Update C[k, j] using A[i, k] * B[i, j]
                C[k, j] += alpha * B[i, j] * A[i, k]
                #   - Accumulate contribution for C[i, j]
